select throws_ok($$select public.create_evalia_model('QA E1 legacy','M',360,array['e1070000-0000-4000-8000-000000000031']::uuid[],0,'e1070000-0000-4000-8000-000000000025',null)$$,'23505',null,'solicitud histórica no se confirma sin huella');
set local request.jwt.claim.sub='e1070000-0000-4000-8000-000000000002';
set local request.jwt.claims='{"sub":"e1070000-0000-4000-8000-000000000002","session_id":"e1070000-0000-4000-8000-000000000012","aal":"aal1"}';
